SHIPPING_RATES = {
  domestic: {
    heavy: { express: 50, standard: 20 },
    light: { express: 25, standard: 5 }
  },
  international: {
    heavy: { express: 100, standard: 40 },
    light: { express: 60, standard: 15 }
  }
}.freeze

def shipping_cost(order)
  region = order[:country] == "US" ? :domestic : :international
  size = order[:weight] > 10 ? :heavy : :light
  speed = order[:express] ? :express : :standard

  SHIPPING_RATES.dig(region, size, speed)
end
